//! Byte-for-byte parity with the spec's TypeScript reference.
//! Vectors are generated by `conformance/generator/canonical.gen.ts`.

use contextos_contract::canonical::{canonicalize, legacy_stable_stringify, sha256_canonical, sha256_text};
use serde_json::Value;

fn vectors(name: &str) -> Vec<Value> {
    let path = format!("{}/../../conformance/vectors/{name}", env!("CARGO_MANIFEST_DIR"));
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    serde_json::from_str(&text).expect("vector file is JSON")
}

#[test]
fn legacy_hash_keeps_the_original_unicode_collation() {
    // ICU 2.4 reorders these keys and changes already-persisted compiler hashes.
    // Changing the legacy encoding requires a versioned migration, not a dependency bump.
    let value = serde_json::json!({"a": 0, "\u{05c8}": 0});
    let encoded = legacy_stable_stringify(&value);
    assert_eq!(encoded, "{\"a\":0,\"\u{05c8}\":0}");
    assert_eq!(
        sha256_text(&encoded),
        "sha256:fe17994aa7a316a4cebdb6e707c88953af3959b3e211466bdfc42202780c24a5"
    );
}

#[test]
fn canonical_encodings_match_reference() {
    let cases = vectors("canonical.json");
    assert_ne!(cases, [] as [Value; 0]);
    for case in cases {
        let input = &case["input"];
        assert_eq!(
            canonicalize(input).unwrap(),
            case["jcs"].as_str().unwrap(),
            "jcs of {input}"
        );
        assert_eq!(sha256_canonical(input).unwrap(), case["jcs_sha256"].as_str().unwrap());
        assert_eq!(
            legacy_stable_stringify(input),
            case["legacy"].as_str().unwrap(),
            "legacy of {input}"
        );
    }
}
